using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;using UnityEditor.SceneManagement;
public static class PolishCampus {
 const string R="Assets/_FireSafety/CampusExterior/",S="Assets/ThirdParty/SchoolExpansion/tree_small_02/textures/";
 static Bounds B(GameObject g){var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
 static Mesh Read(int lod){using(var r=new BinaryReader(File.OpenRead("../SourceAssets/CampusExterior/tree-campus-lod"+lod+".bin"))){int parts=r.ReadInt32();var v=new List<Vector3>();var uv=new List<Vector2>();var normals=new List<Vector3>();var sub=new List<int[]>();for(int s=0;s<parts;s++){int n=r.ReadInt32(),count=r.ReadInt32(),offset=v.Count;for(int i=0;i<n;i++){v.Add(new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle()));uv.Add(new Vector2(r.ReadSingle(),r.ReadSingle()));normals.Add(new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle()).normalized);}var indices=new int[count];for(int i=0;i<count;i++)indices[i]=r.ReadInt32()+offset;sub.Add(indices);}var mesh=new Mesh{name="Leafy tree LOD"+lod,indexFormat=IndexFormat.UInt32};mesh.SetVertices(v);mesh.SetNormals(normals);mesh.SetUVs(0,uv);mesh.subMeshCount=parts;for(int i=0;i<parts;i++)mesh.SetTriangles(sub[i],i);mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,R+"Meshes/LeafyTree-LOD"+lod+".asset");return mesh;}}
 static Material TreeMaterial(string name,string diffuse,string normal,bool leaf){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(diffuse));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(normal));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.45f);m.SetFloat("_Smoothness",.19f);m.SetFloat("_Cull",0);if(leaf){m.SetFloat("_AlphaClip",1);m.SetFloat("_Cutoff",.32f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}m.enableInstancing=true;AssetDatabase.CreateAsset(m,R+"Materials/"+name+".mat");return m;}
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit Mode required");if(GameObject.Find("Campus leafy trees"))throw new Exception("Already polished");Directory.CreateDirectory(R+"Textures");AssetDatabase.Refresh();
  // Pack source opacity into the base-map alpha channel for Unity's standard cutout shader.
  var diffuse=new Texture2D(2,2);diffuse.LoadImage(File.ReadAllBytes(S+"tree_small_02_leaves_diff_1k.png"));var alpha=new Texture2D(2,2);alpha.LoadImage(File.ReadAllBytes(S+"tree_small_02_leaves_alpha_1k.png"));var pixels=diffuse.GetPixels();for(int y=0;y<diffuse.height;y++)for(int x=0;x<diffuse.width;x++)pixels[y*diffuse.width+x].a=alpha.GetPixelBilinear((float)x/diffuse.width,(float)y/diffuse.height).r;diffuse.SetPixels(pixels);diffuse.Apply();var packed=R+"Textures/TreeLeaves_BaseColorAlpha.png";File.WriteAllBytes(packed,diffuse.EncodeToPNG());UnityEngine.Object.DestroyImmediate(diffuse);UnityEngine.Object.DestroyImmediate(alpha);AssetDatabase.ImportAsset(packed);var importer=(TextureImporter)AssetImporter.GetAtPath(packed);importer.sRGBTexture=true;importer.alphaIsTransparency=true;importer.mipmapEnabled=true;importer.maxTextureSize=1024;importer.textureCompression=TextureImporterCompression.Compressed;importer.SaveAndReimport();
  var mats=new[]{TreeMaterial("Leafy tree branches",S+"tree_small_02_branch_diff_1k.png",S+"tree_small_02_branch_nor_gl_1k.png",false),TreeMaterial("Leafy tree leaves",packed,S+"tree_small_02_leaves_nor_gl_1k.png",true),TreeMaterial("Leafy tree trunk",S+"tree_small_02_diff_1k.jpg",S+"tree_small_02_nor_gl_1k.exr",false)};
  var source=new GameObject("Optimized leafy campus tree");var renderers=new List<Renderer>();var meshes=new[]{Read(0),Read(1)};for(int i=0;i<2;i++){var g=new GameObject("LOD"+i,typeof(MeshFilter),typeof(MeshRenderer));g.transform.SetParent(source.transform,false);g.GetComponent<MeshFilter>().sharedMesh=meshes[i];var renderer=g.GetComponent<MeshRenderer>();renderer.sharedMaterials=mats;renderers.Add(renderer);g.layer=30;}
  var bounds=meshes[0].bounds;float scale=6.8f/bounds.size.y;foreach(Transform t in source.transform){t.localScale=Vector3.one*scale;t.localPosition=-new Vector3(bounds.center.x,bounds.min.y,bounds.center.z)*scale;}
  var lodGroup=source.AddComponent<LODGroup>();lodGroup.SetLODs(new[]{new LOD(.18f,new[]{renderers[0]}),new LOD(.014f,new[]{renderers[1]})});lodGroup.RecalculateBounds();var collider=source.AddComponent<CapsuleCollider>();collider.center=Vector3.up*1.8f;collider.height=3.6f;collider.radius=.24f;
  var prefab=PrefabUtility.SaveAsPrefabAsset(source,R+"Prefabs/Optimized leafy campus tree.prefab");UnityEngine.Object.DestroyImmediate(source);
  var parent=new GameObject("Campus leafy trees").transform;parent.SetParent(GameObject.Find("Campus exterior upgrade").transform,false);
  var old=GameObject.Find("School expansion/Courtyard landscaping").transform;int index=0;foreach(Transform t in old)if(t.name.Contains("quiver_tree")){t.gameObject.SetActive(false);var tree=(GameObject)PrefabUtility.InstantiatePrefab(prefab,parent);tree.transform.position=t.position;tree.transform.rotation=Quaternion.Euler(0,35+index++*83,0);}
  // Use the fuller licensed shrub variant with the existing compatible foliage materials.
  var existingShrub=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_FireSafety/SchoolExpansion/Prefabs/shrub_01_garden.prefab");var shrubMats=existingShrub.GetComponentInChildren<Renderer>().sharedMaterials;
  var fullModel=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ThirdParty/SchoolExpansion/shrub_01/shrub_01.fbx"));foreach(var f in fullModel.GetComponentsInChildren<MeshFilter>())if(!f.name.Contains("_a_"))UnityEngine.Object.DestroyImmediate(f.gameObject);var shrubRoot=new GameObject("Fuller campus shrub");fullModel.transform.SetParent(shrubRoot.transform,false);var sb=B(fullModel);fullModel.transform.localScale*=.95f/sb.size.y;sb=B(fullModel);fullModel.transform.position-=new Vector3(sb.center.x,sb.min.y,sb.center.z);foreach(var renderer in fullModel.GetComponentsInChildren<Renderer>()){renderer.sharedMaterials=shrubMats;renderer.shadowCastingMode=ShadowCastingMode.Off;renderer.gameObject.layer=30;}var slod=shrubRoot.AddComponent<LODGroup>();slod.SetLODs(new[]{new LOD(.012f,shrubRoot.GetComponentsInChildren<Renderer>())});slod.RecalculateBounds();var shrubPrefab=PrefabUtility.SaveAsPrefabAsset(shrubRoot,R+"Prefabs/Fuller campus shrub.prefab");UnityEngine.Object.DestroyImmediate(shrubRoot);
  var targets=GameObject.Find("Campus exterior upgrade/Campus planting and corridor furniture").transform.Cast<Transform>().Where(t=>t.name=="Facade shrub").Concat(old.Cast<Transform>().Where(t=>t.name.Contains("shrub_01"))).ToArray();foreach(var t in targets){var g=(GameObject)PrefabUtility.InstantiatePrefab(shrubPrefab,parent);g.transform.position=t.position;g.transform.rotation=t.rotation;t.gameObject.SetActive(false);}
  var tiles=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="Campus pale marble corridor tiles"};tiles.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/ThirdParty/CampusExterior/floor_tiles_04/floor_tiles_04_diff_2k.jpg"));tiles.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/ThirdParty/CampusExterior/floor_tiles_04/floor_tiles_04_nor_gl_2k.png"));tiles.EnableKeyword("_NORMALMAP");tiles.SetFloat("_BumpScale",.25f);tiles.SetFloat("_Smoothness",.38f);tiles.enableInstancing=true;AssetDatabase.CreateAsset(tiles,R+"Materials/Campus pale marble corridor tiles.mat");
  var corridor=GameObject.Find("Campus exterior upgrade/Ground floor covered corridor").transform;foreach(var renderer in corridor.GetComponentsInChildren<Renderer>())if(renderer.sharedMaterial.name=="Campus corridor stone tile")renderer.sharedMaterial=tiles;
  // Interior sunlight is preserved. A cheaper unshadowed fill lights exterior-only renderers.
  foreach(var renderer in GameObject.Find("Campus exterior upgrade").GetComponentsInChildren<Renderer>())if(!renderer.GetComponent<Collider>())renderer.gameObject.layer=30;
  var fill=new GameObject("Exterior facade daylight fill").AddComponent<Light>();fill.transform.SetParent(GameObject.Find("Campus exterior upgrade").transform,false);fill.type=LightType.Directional;fill.transform.rotation=Quaternion.Euler(42,-105,0);fill.intensity=1.1f;fill.color=new Color(1,.95f,.85f);fill.shadows=LightShadows.None;fill.cullingMask=1<<30;
  // Avoid self-shadow speckling on extremely thin decorative overlays.
  foreach(var renderer in corridor.GetComponentsInChildren<Renderer>())renderer.shadowCastingMode=ShadowCastingMode.Off;
  EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();return new{leafyTrees=index,fullerShrubs=targets.Length,lod0Triangles=meshes[0].triangles.Length/3,lod1Triangles=meshes[1].triangles.Length/3};
 }
}
